-- QUIAR: esquema inicial reconstruido desde Backend/routes.
-- Ejecutar UNA VEZ en un proyecto Supabase vacio, desde SQL Editor.
-- Conserva camelCase: las consultas PostgreSQL deben usar comillas dobles.
-- No contiene datos de prueba ni configura Supabase Auth.
BEGIN;

CREATE TABLE public.rol (
    "idRol" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nombreRol" text NOT NULL UNIQUE,
    descripcion text
);

CREATE TABLE public.permiso (
    "idPermiso" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nombrePermiso" text NOT NULL UNIQUE,
    descripcion text
);

CREATE TABLE public.rol_permiso (
    "idRol" integer NOT NULL REFERENCES public.rol("idRol") ON DELETE CASCADE,
    "idPermiso" integer NOT NULL REFERENCES public.permiso("idPermiso") ON DELETE CASCADE,
    PRIMARY KEY ("idRol", "idPermiso")
);

CREATE TABLE public.sector (
    "idSector" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nombreSector" text NOT NULL UNIQUE
);

CREATE TABLE public.usuario (
    "idUsuario" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nombreCompleto" text NOT NULL,
    correo text UNIQUE,
    "idRol" integer REFERENCES public.rol("idRol") ON DELETE SET NULL,
    estado text NOT NULL DEFAULT 'Activo'
);

CREATE TABLE public.cliente (
    "idCliente" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    empresa text NOT NULL,
    contacto text,
    puesto text,
    telefono text,
    correo text,
    ciudad text,
    "tipoCliente" text,
    estado text NOT NULL DEFAULT 'Activo',
    "idSector" integer REFERENCES public.sector("idSector") ON DELETE SET NULL
);

CREATE TABLE public.proveedor (
    "idProveedor" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nombreProveedor" text NOT NULL,
    contacto text,
    telefono text,
    correo text,
    "paisOrigen" text,
    "tipoProveedor" text,
    estado text NOT NULL DEFAULT 'Activo'
);

CREATE TABLE public.producto (
    "codigoProducto" text PRIMARY KEY,
    "idProveedor" integer REFERENCES public.proveedor("idProveedor") ON DELETE SET NULL,
    producto text NOT NULL,
    categoria text,
    marca text,
    stock numeric(14,3) NOT NULL DEFAULT 0 CHECK (stock >= 0),
    "minStock" numeric(14,3) NOT NULL DEFAULT 0 CHECK ("minStock" >= 0),
    "precioCompra" numeric(14,2) NOT NULL DEFAULT 0 CHECK ("precioCompra" >= 0),
    "precioVenta" numeric(14,2) NOT NULL DEFAULT 0 CHECK ("precioVenta" >= 0),
    origen text,
    ubicacion text
);

CREATE TABLE public.movimiento_inventario (
    "idMovimiento" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "codigoProducto" text NOT NULL REFERENCES public.producto("codigoProducto"),
    "idUsuario" integer REFERENCES public.usuario("idUsuario") ON DELETE SET NULL,
    "tipoMovimiento" text NOT NULL CHECK (upper("tipoMovimiento") IN ('ENTRADA', 'SALIDA')),
    cantidad numeric(14,3) NOT NULL CHECK (cantidad >= 0),
    "fechaMovimiento" timestamptz NOT NULL DEFAULT now(),
    referencia text
);

CREATE TABLE public.cotizacion_pedido (
    "idPedido" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "idCliente" integer REFERENCES public.cliente("idCliente") ON DELETE SET NULL,
    "idUsuario" integer REFERENCES public.usuario("idUsuario") ON DELETE SET NULL,
    folio text NOT NULL DEFAULT 'Sin Folio',
    fecha date NOT NULL DEFAULT CURRENT_DATE,
    subtotal numeric(14,2) NOT NULL DEFAULT 0 CHECK (subtotal >= 0),
    "descuentoTotal" numeric(14,2) NOT NULL DEFAULT 0 CHECK ("descuentoTotal" >= 0),
    iva numeric(14,2) NOT NULL DEFAULT 0 CHECK (iva >= 0),
    total numeric(14,2) NOT NULL DEFAULT 0 CHECK (total >= 0),
    estado text NOT NULL DEFAULT 'Pendiente'
);

CREATE TABLE public.detalle_pedido (
    "idDetalle" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "idPedido" integer NOT NULL REFERENCES public.cotizacion_pedido("idPedido") ON DELETE CASCADE,
    "codigoProducto" text NOT NULL REFERENCES public.producto("codigoProducto"),
    cantidad numeric(14,3) NOT NULL CHECK (cantidad > 0),
    "precioVenta" numeric(14,2) NOT NULL DEFAULT 0 CHECK ("precioVenta" >= 0),
    descuento numeric(14,2) NOT NULL DEFAULT 0 CHECK (descuento >= 0),
    "subtotalLinea" numeric(14,2) NOT NULL DEFAULT 0 CHECK ("subtotalLinea" >= 0)
);

CREATE TABLE public.especialista (
    "idEspecialista" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre text NOT NULL,
    especialidad text,
    telefono text,
    estado text NOT NULL DEFAULT 'Activo'
);

CREATE TABLE public.servicio_especializado (
    "idServicio" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "idCliente" integer REFERENCES public.cliente("idCliente") ON DELETE SET NULL,
    "idEspecialista" integer REFERENCES public.especialista("idEspecialista") ON DELETE SET NULL,
    "descripcionRequerimiento" text NOT NULL,
    "fechaSolicitud" timestamptz NOT NULL DEFAULT now(),
    "fechaProgramada" timestamptz,
    estado text NOT NULL DEFAULT 'Pendiente'
);

CREATE INDEX ON public.rol_permiso ("idPermiso");
CREATE INDEX ON public.usuario ("idRol");
CREATE INDEX ON public.cliente ("idSector");
CREATE INDEX ON public.producto ("idProveedor");
CREATE INDEX ON public.movimiento_inventario ("codigoProducto");
CREATE INDEX ON public.movimiento_inventario ("idUsuario");
CREATE INDEX ON public.movimiento_inventario ("fechaMovimiento" DESC);
CREATE INDEX ON public.cotizacion_pedido ("idCliente");
CREATE INDEX ON public.cotizacion_pedido ("idUsuario");
CREATE INDEX ON public.cotizacion_pedido (fecha DESC);
CREATE INDEX ON public.detalle_pedido ("idPedido");
CREATE INDEX ON public.detalle_pedido ("codigoProducto");
CREATE INDEX ON public.servicio_especializado ("idCliente");
CREATE INDEX ON public.servicio_especializado ("idEspecialista");
CREATE INDEX ON public.servicio_especializado ("fechaSolicitud" DESC);

-- Acceso previsto mediante Express con conexion PostgreSQL del servidor.
-- Sin politicas: anon/authenticated no tienen acceso por la Data API.
ALTER TABLE public.rol ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.permiso ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.rol_permiso ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sector ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.usuario ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cliente ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.proveedor ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.producto ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.movimiento_inventario ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cotizacion_pedido ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.detalle_pedido ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.especialista ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.servicio_especializado ENABLE ROW LEVEL SECURITY;

COMMIT;
